package cn.charlotte.pit.menu.genesis;import cn.charlotte.pit.Util;import cn.charlotte.pit.data.PlayerProfile;import cn.charlotte.pit.events.genesis.team.GenesisTeam;import cn.charlotte.pit.item.PitItems;import cn.charlotte.pit.item.type.mythic.MythicBowItem;import cn.charlotte.pit.item.type.mythic.MythicLeggingsItem;import cn.charlotte.pit.item.type.mythic.MythicSwordItem;import cn.charlotte.pit.util.RandomList;import cn.charlotte.pit.util.chat.CC;import cn.charlotte.pit.util.item.ItemBuilder;import cn.charlotte.pit.util.menu.Button;import cn.charlotte.pit.util.menu.Menu;import cn.charlotte.pit.util.random.RandomUtil;import org.bukkit.Color;import org.bukkit.Material;import org.bukkit.Sound;import org.bukkit.entity.Player;import org.bukkit.event.inventory.ClickType;import org.bukkit.inventory.ItemStack;import java.util.*;import java.util.stream.Collectors;import java.util.stream.IntStream;public class GenesisBuyMenu extends Menu {    private final RandomList<String> randomList = new RandomList<>(            Map.entry("1coin", 80),            Map.entry("2coin", 60),            Map.entry("5coin", 40),            Map.entry("1wcoin", 10),            Map.entry("1xp", 80),            Map.entry("2xp", 60),            Map.entry("5xp", 40),            Map.entry("1wxp", 10),            Map.entry("coal", 50),            Map.entry("2coal", 10),            Map.entry("1box", 50),            Map.entry("2box", 25),            Map.entry("3box", 10),            Map.entry("1mythicitem", 50),            Map.entry("2mythicitem", 15),            Map.entry("item", 1),            Map.entry("16sugar", 50),            Map.entry("64wheat", 50),            Map.entry("milk", 10),            Map.entry("1renown", 10),            Map.entry("2renown", 5),            Map.entry("banner", 60)    );    @Override    public String getTitle(Player player) {        PlayerProfile profile = Util.getPitProfile(player);        return (profile.getGenesisData().getTeam() == GenesisTeam.ANGEL ? "天使" : "恶魔") + "-商店 - " +                profile.getGenesisData().getPoints() + "点数";    }    @Override    public int getSize() {        return 5 * 9;    }    @Override    public Map<Integer, Button> getButtons(Player player) {        Map<Integer, String> buylist = Deserializer(Util.getPitProfile(player).getGenesisData().getBuyList());        if (buylist.isEmpty()) {            List<String> textlist = generateUniqueRandomList(3);            buylist = IntStream.range(0, 3)                    .boxed()                    .collect(Collectors.toMap(i -> i, textlist::get));            Util.getPitProfile(player).getGenesisData().setBuyList(Serializer(buylist));        }        int[] buttonSlots = {10, 13, 16};        Map<Integer, String> finalBuylist = buylist;        Map<Integer, Button> buttons = IntStream.range(0, 3)                .boxed()                .collect(Collectors.toMap(i -> buttonSlots[i], i -> createbutton(finalBuylist.get(i))));        buttons.put(40, createrefreshbutton());        buttons.put(36, createbackbutton());        return buttons;    }    private String extortionate(String text, boolean angel) {        switch (text) {            case "1coin" -> {                return "&e1000金币";            }            case "2coin" -> {                return "&e2000金币";            }            case "5coin" -> {                return "&e5000金币";            }            case "1wcoin" -> {                return "&e10000金币";            }            case "1xp" -> {                return "&b1000经验";            }            case "2xp" -> {                return "&b2000经验";            }            case "5xp" -> {                return "&b5000经验";            }            case "1wxp" -> {                return "&b10000经验";            }            case "coal" -> {                return "&5暗聚块";            }            case "2coal" -> {                return "&5暗聚块 &f* 2";            }            case "1box" -> {                return "&e行动礼盒";            }            case "2box" -> {                return "&e行动礼盒 &f* 2";            }            case "3box" -> {                return "&e行动礼盒 &f* 3";            }            case "1mythicitem" -> {                return "&d随机神话装备";            }            case "2mythicitem" -> {                return "&d随机神话装备 &f* 2";            }            case "item" -> {                return angel ? "&f天使之甲" : "&c终末之靴";            }            case "16sugar" -> {                return "&a糖 &f* 16";            }            case "64wheat" -> {                return "&e小麦 &f* 64";            }            case "milk" -> {                return "&f牛奶";            }            case "1renown" -> {                return "&b1声望";            }            case "2renown" -> {                return "2声望";            }            case "banner" -> {                return "&a增益旗帜";            }        }        return "已购买过该商品";    }    private int expropriate(String text) {        switch (text) {            case "1coin", "1xp" -> {                return 150;            }            case "2coin", "2xp" -> {                return 250;            }            case "5coin", "5xp", "banner", "2box" -> {                return 500;            }            case "1wcoin", "1wxp", "2mythicitem" -> {                return 1000;            }            case "coal" -> {                return 4000;            }            case "2coal" -> {                return 6000;            }            case "1box" -> {                return 200;            }            case "3box" -> {                return 700;            }            case "1mythicitem" -> {                return 750;            }            case "item", "milk", "1renown" -> {                return 15000;            }            case "16sugar" -> {                return 80;            }            case "64wheat" -> {                return 800;            }            case "2renown" -> {                return 50000;            }        }        return 99999999;    }    private Material prototype(String text, boolean angel) {        switch (text) {            case "1coin", "2coin", "5coin", "1wcoin" -> {                return Material.GOLD_BLOCK;            }            case "1xp", "2xp", "5xp", "1wxp" -> {                return Material.EXPERIENCE_BOTTLE;            }            case "coal", "2coal" -> {                return Material.COAL;            }            case "1box", "2box", "3box" -> {                return Material.CHEST;            }            case "1mythicitem", "2mythicitem" -> {                return Material.GOLDEN_SWORD;            }            case "item" -> {                return angel ? Material.DIAMOND_CHESTPLATE : Material.LEATHER_BOOTS;            }            case "16sugar" -> {                return Material.SUGAR;            }            case "64wheat" -> {                return Material.WHEAT;            }            case "milk" -> {                return Material.MILK_BUCKET;            }            case "1renown", "2renown" -> {                return Material.DIAMOND_BLOCK;            }            case "banner" -> {                return Material.GREEN_BANNER;            }        }        return Material.BARRIER;    }    private boolean coextensive(String text, Player player) {        PlayerProfile profile = Util.getPitProfile(player);        int points = profile.getGenesisData().getPoints();        if (points < expropriate(text)) {            player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_NO, 1.0f, 1.0f);            player.sendMessage(CC.translate("&7你的点数不足,无法兑换! &c" + points + "/" + expropriate(text)));            return false;        }        switch (text) {            case "1coin" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                profile.setCoins(profile.getCoins() + 1000);                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "2coin" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                profile.setCoins(profile.getCoins() + 2000);                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "5coin" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                profile.setCoins(profile.getCoins() + 5000);                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "1wcoin" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                profile.setCoins(profile.getCoins() + 10000);                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "1xp" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                profile.setExperience(profile.getExperience() + 1000);                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "2xp" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                profile.setExperience(profile.getExperience() + 2000);                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "5xp" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                profile.setExperience(profile.getExperience() + 5000);                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "1wxp" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                profile.setExperience(profile.getExperience() + 10000);                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "coal" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                player.getInventory().addItem(PitItems.CHUNK_OF_VILE.toItemStack());                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "2coal" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                player.getInventory().addItem(PitItems.CHUNK_OF_VILE.toManyItem(2));                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "1box" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                player.getInventory().addItem(PitItems.ACTION_GIFT_BOX.toItemStack());                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "2box" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                player.getInventory().addItem(PitItems.ACTION_GIFT_BOX.toManyItem(2));                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "3box" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                player.getInventory().addItem(PitItems.ACTION_GIFT_BOX.toManyItem(3));                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "1mythicitem" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                ItemStack mythic = RandomUtil.helpMeToChooseOne(                        new MythicSwordItem().toItemStack(),                        new MythicBowItem().toItemStack(),                        new MythicLeggingsItem().toItemStack()                );                if (mythic != null) {                    player.getInventory().addItem(mythic);                }                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "2mythicitem" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                ItemStack mythic = RandomUtil.helpMeToChooseOne(                        new MythicSwordItem().toItemStack(),                        new MythicBowItem().toItemStack(),                        new MythicLeggingsItem().toItemStack()                );                if (mythic != null) {                    player.getInventory().addItem(mythic);                }                ItemStack mythic2 = RandomUtil.helpMeToChooseOne(                        new MythicSwordItem().toItemStack(),                        new MythicBowItem().toItemStack(),                        new MythicLeggingsItem().toItemStack()                );                if (mythic2 != null) {                    player.getInventory().addItem(mythic2);                }                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "item" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                if (profile.getGenesisData().getTeam() == GenesisTeam.ANGEL) {                    player.getInventory().addItem(PitItems.ANGEL_CHEST_PLATE.toItemStack());                } else {                    player.getInventory().addItem(PitItems.ARMAGEDDON_BOOTS.toItemStack());                }                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "16sugar" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                player.getInventory().addItem(PitItems.SUGAR.toManyItem(16));                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "64wheat" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                player.getInventory().addItem(PitItems.WHEAT.toManyItem(64));                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "1renown" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                profile.setRenown(profile.getRenown() + 1);                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "2renown" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                profile.setRenown(profile.getRenown() + 2);                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "banner" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                player.getInventory().addItem(PitItems.GAIN_BANNER.toManyItem(16));                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }            case "milk" -> {                player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_YES, 1.0f, 1.0f);                player.getInventory().addItem(PitItems.MILK_BUCKET.toItemStack());                profile.getGenesisData().setPoints(points - expropriate(text));                player.sendMessage(CC.translate("&e兑换成功!你还剩下 &a" + profile.getGenesisData().getPoints()));                return true;            }        }        return false;    }    private Map<String, Integer> Serializer(Map<Integer, String> map) {        if (map == null) {            return new HashMap<>();        }        Map<String, Integer> result = new HashMap<>();        for (Map.Entry<Integer, String> entry : map.entrySet()) {            result.put(entry.getValue(), entry.getKey());        }        return result;    }    private Map<Integer, String> Deserializer(Map<String, Integer> map) {        if (map == null) {            return new HashMap<>();        }        Map<Integer, String> result = new HashMap<>();        for (Map.Entry<String, Integer> entry : map.entrySet()) {            result.put(entry.getValue(), entry.getKey());        }        return result;    }    public List<String> generateUniqueRandomList(int count) {        if (count <= 0) {            return new ArrayList<>();        }        Set<String> usedValues = new HashSet<>();        List<String> result = new ArrayList<>();        int maxPossible = 3;        if (count > maxPossible) {            count = maxPossible;        }        int maxAttempts = count * 10;        while (result.size() < count && maxAttempts > 0) {            String randomValue = randomList.random();            if (!usedValues.contains(randomValue)) {                usedValues.add(randomValue);                result.add(randomValue);            }            maxAttempts--;        }        return result;    }    private Button createbutton(String text) {        return new Button() {            @Override            public ItemStack getButtonItem(Player player) {                boolean angel = Util.getPitProfile(player).getGenesisData().getTeam() == GenesisTeam.ANGEL;                if (text == null) {                    return new ItemBuilder(Material.BARRIER)                            .name("已购买过该商品")                            .lore("", "你已购买过该商品", "")                            .build();                } else if (!angel && text.equals("item")) {                    return new ItemBuilder(prototype(text, false))                            .name(extortionate(text, false))                            .setLetherColor(Color.RED)                            .lore("", (expropriate(text) == 99999999 ? "你已购买过该商品" : "&f价格:" + expropriate(text) + "点数"), "")                            .build();                } else {                    return new ItemBuilder(prototype(text, angel))                            .name(extortionate(text, angel))                            .lore("", (expropriate(text) == 99999999 ? "你已购买过该商品" : "&f价格:" + expropriate(text) + "点数"), "")                            .build();                }            }            @Override            public void clicked(Player player, int slot, ClickType clickType, int hotbarButton, ItemStack currentItem) {                PlayerProfile profile = Util.getPitProfile(player);                Map<Integer, String> map = Deserializer(profile.getGenesisData().getBuyList());                final Map<Integer, Integer> buttonslots = Map.of(                        10, 0,                        13, 1,                        16, 2                );                if (coextensive(text, player)) {                    map.remove(buttonslots.get(slot));                    map.put(buttonslots.get(slot), "Null");                    profile.getGenesisData().setBuyList(Serializer(map));                    new GenesisBuyMenu().openMenu(player);                }            }            @Override            public boolean shouldUpdate(Player player, int slot, ClickType clickType) {                return true;            }        };    }    private Button createrefreshbutton() {        return new Button() {            @Override            public ItemStack getButtonItem(Player player) {                return new ItemBuilder(Material.EMERALD)                        .name("&a刷新")                        .lore("", "&f价格: 100 点数", "")                        .build();            }            @Override            public void clicked(Player player, int slot, ClickType clickType, int hotbarButton, ItemStack currentItem) {                PlayerProfile profile = Util.getPitProfile(player);                if (profile.getGenesisData().getPoints() < 100) {                    player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_NO, 1.0f, 1.0f);                    player.sendMessage(CC.translate("&c你没有点数来刷新"));                    return;                }                profile.getGenesisData().setPoints(profile.getGenesisData().getPoints() - 100);                profile.getGenesisData().setBuyList(new HashMap<>());                new GenesisBuyMenu().openMenu(player);            }            @Override            public boolean shouldUpdate(Player player, int slot, ClickType clickType) {                return true;            }        };    }    private Button createbackbutton() {        return new Button() {            @Override            public ItemStack getButtonItem(Player player) {                return new ItemBuilder(Material.FEATHER)                        .name("&f返回")                        .lore("", "&f左键点击返回", "")                        .build();            }            @Override            public void clicked(Player player, int slot, ClickType clickType, int hotbarButton, ItemStack currentItem) {                new GenesisMenu(Util.getPitProfile(player).getGenesisData().getTeam()).openMenu(player);            }            @Override            public boolean shouldUpdate(Player player, int slot, ClickType clickType) {                return true;            }        };    }}